sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_percentual_da_rcl_investimento_pago":"percentual_da_rcl_investimento_pago",
       "v_investimento_pago":"investimento_pago",
       "v_percentual_da_rcl_investimento_liquidado":"percentual_da_rcl_investimento_liquidado",
       "v_investimento_liquidado":"investimento_liquidado",
       "v_percentual_da_rcl_investimento_empenhado":"percentual_da_rcl_investimento_empenhado",
       "v_investimento_empenhado":"investimento_empenhado",
       "v_receita_corrente_liquida":"receita_corrente_liquida",
       "v_ano":"ano"
   };

   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

   outputs.percentual_da_rcl_investimento_pago = fieldMapping['v_percentual_da_rcl_investimento_pago'];
   outputs.investimento_pago = fieldMapping['v_investimento_pago'];
   outputs.percentual_da_rcl_investimento_liquidado = fieldMapping['v_percentual_da_rcl_investimento_liquidado'];
   outputs.investimento_liquidado = fieldMapping['v_investimento_liquidado'];
   outputs.percentual_da_rcl_investimento_empenhado = fieldMapping['v_percentual_da_rcl_investimento_empenhado'];
   outputs.investimento_empenhado = fieldMapping['v_investimento_empenhado'];
   outputs.receita_corrente_liquida = fieldMapping['v_receita_corrente_liquida'];
   outputs.ano = fieldMapping['v_ano'];

})(inputs, outputs);

